    ["05-d1"] = {name="Salão dos Thanes", entrance="Altaforja 27.63, 47.83", pickup="Pegue as missões da masmorra ao passar: Dun Morogh e Loch Modan. Assim não precisa voltar antes de entrar.", pickupS={{"Pegue as missões da masmorra ao passar: Dun Morogh e Loch Modan"}, {"Assim não precisa voltar antes de entrar"}}, steps={[1]={npc="Mapa Ferro Negro", npcObj=true, tag="Pré-requisito de masmorra"}, [2]={npc="Vidente da Terra Farsen", tgt="Vidente da Terra Farsen", tag="Pré-requisito de masmorra"}, [3]={npc="Vidente da Terra Farsen", tgt="Vidente da Terra Farsen"}, [4]={npc="Afadra Dunwall", tgt="Afadra Dunwall"}, [5]={npc="Tom Mão-leve", tgt="Tom Mão-leve"}, [6]={npc="Ghostly Attendant", tgt="Ghostly Attendant"}, [7]={text="Entrada: Salão dos Thanes"}, [8]={npc="Ghostly Attendant", tgt="Ghostly Attendant"}, [9]={hint="Mate 15 Aparições Enfurecidas, 10 Almas Atormentadas e dê descanso ao espírito de Sidermar."}, [10]={hint="Colete 8 Heranças Enânicas no Salão dos Thanes."}, [11]={hint="Adentre o Salão dos Thanes abaixo da Antiga Altaforja e corte a cabeça de Durgen Martelúgubre."}, [12]={npc="Treaty of Understanding", npcObj=true, desc="Clique com o botão direito em Tratado de Entendimento na bolsa para iniciar a missão. O chefe final usa Medo com cerca de 35% de vida. Limpe os lacaios primeiro e depois puxe o chefe para a sala anterior. Ao lado de quem dá a missão há uma alavanca. Puxe para abrir a porta e saia em linha reta."}, [13]={npc="Tom Mão-leve", tgt="Tom Mão-leve"}, [14]={npc="Afadra Dunwall", tgt="Afadra Dunwall"}, [15]={npc="Rei Magni Barbabronze", tgt="Rei Magni Barbabronze"}, [16]={npc="Rei Magni Barbabronze", tgt="Rei Magni Barbabronze"}}},
