    ["04-47"] = {steps={[1]={npc="Arathandris Argencélio", tgt="Arathandris Argencélio"}, [2]={npc="Grazle", tgt="Grazle"}, [3]={npc="Greta Musgo no Casco", tgt="Greta Musgo no Casco"}, [4]={npc="Eridan Brisazul", tgt="Eridan Brisazul"}, [5]={npc="Taronn Pena Vermelha", tgt="Taronn Pena Vermelha", tag="Opcional"}, [6]={hint="Grazle quer que você prove seu valor matando 6 Guerreiros de Lenha Morta, 6 Desbravadores de Lenha Morta e 6 Jardineiros de Lenha Morta. Quando você terminar, fale novamente com ele na parte sul da Selva Maleva, perto do Santuário Esmeralda."}, [7]={npc="Grazle", tgt="Grazle"}, [8]={npc="Grazle", tgt="Grazle"}, [9]={hint="Mate 11 Devotos Vis Flamejade, 9 Assombrantes Flamejade, 9 Desgarrados Flamejade e Xavathras. Fale novamente com Eridan Brisazul na Selva Maleva quando a tarefa estiver completa."}, [10]={hint="Entre em Jaedenar e mate 4 Cães de Jaedenar, 4 Guardas de Jaedenar, 6 Adeptos de Jaedenar e 6 Sectários de Jaedenar. Depois, fale novamente com Greta Musgo no Casco, na Selva Maleva."}, [11]={npc="Eridan Brisazul", tgt="Eridan Brisazul"}, [12]={npc="Eridan Brisazul", tgt="Eridan Brisazul"}, [13]={npc="Greta Musgo no Casco", tgt="Greta Musgo no Casco"}, [14]={npc="Greta Musgo no Casco", tgt="Greta Musgo no Casco"}, [15]={hint="Leve o Cantil Vazio para o Poço Lunar no meio de Jaedenar e encha-o. Depois, fale novamente com Greta Musgo no Casco na Selva Maleva."}, [17]={hint="Procure e destrua 2 Feras Entrópicas e 2 Horrores Entrópicos enquanto explora o Vale das Escaras Pungentes. Depois de ver se as crateras ainda estão cheias de água contaminada com vileza, fale novamente com Taronn Pena Vermelha, na Selva Maleva.", tag="Opcional", desc="É um desvio só para isso; não há outros objetivos perto. Se estiver com pressa, pule."}, [18]={hint="Eridan Brisazul, na Selva Maleva, quer que você mate 8 Infernarautos Flamejade, 8 Traidores Flamejade, 8 Trapaceiros Flamejade e Xavaric. Fale novamente com Eridan quando a tarefa estiver concluída."}, [19