    [4284] = {n="Cristais de poder", d="Colete 7 Cristais de Poder de cada uma das seguintes cores: vermelho, azul, amarelo e verde. Leve-os para J.D. Neri no Refúgio do Marshal.", objs={"Cristal de Poder Vermelho", "Cristal de Poder Amarelo", "Cristal de Poder Verde", "Cristal de Poder Azul"}},
    [4285] = {n="A torre norte", d="Descubra a localização da Torre de Cristal Norte, que fica na Cratera Un'Goro.", objs={"Torre de Cristal Norte"}},
    [4286] = {n="Produto de primeira", d="Viaje para o Abismo Rocha Negra e recupere 20 Pochetes Ferro Negro. Fale novamente com Oralius quando tiver completado a tarefa. Você supõe que os anões Ferro Negro de dentro do Abismo Rocha Negra carregam essa tal de \"pochete\".", tgo={{"Feitor Furiadastra", "Carcereiro Furiadastra", "Guarda Furiadastra", "Soldado Raso Furiadastra", "Soldado Furiadastra", "Socorrista Furiadastra", "Oficial Furiadastra", "Camponês de Umbraforja"}}},
    [4287] = {n="A torre leste", d="Descubra a localização da Torre de Cristal Leste, que fica na Cratera Un'Goro.", objs={"Torre de Cristal Leste"}},
    [4288] = {n="A torre oeste", d="Descubra a localização da Torre de Cristal Oeste, que fica na Cratera Un'Goro.", objs={"Torre de Cristal Oeste"}},
    [4289] = {n="Os macacos de Un'Goro", d="Leve 2 Pelagens de Gorila de Un'Goro, 2 Pelagens de Pisoteador de Un'Goro, 2 Pelagens de Trovejador de Un'Goro para Torwa Mateiro na entrada da Cratera Un'Goro.", tgo={{"Gorila de Un'Goro", "Gorila de Un'Goro"}, {"Pisoteador de Un'Goro"}, {"Trovejador de Un'Goro"}}},
    [4290] = {n="A dieta de Lar'korwi", d="Encontre a carcaça mais recente de uma presa morta por Lar'korwi e roube um Pedaço de Carcaça de Manguadonte. Depois disso, fale novamente com Torwa Mateiro na Cratera Un'Goro.", objs={"Carcaça de Manguadonte Fresca"}},
    [4291] = {n="O olfato de Lar'korwi", d="Leve 2 Glândulas de Feromônio de Ravassauro para Torwa Mateiro, que está perto da entrada da Cratera Un'Goro.", tgo={{"Lar'korwi Fêmea"}}},
    [4292] = {n="A isca para Lar'korwi", d="Use o conteúdo do Bornal do Torwa para evocar Lar'korwi e derrotá-lo. Então, leve a Cabeça do Lar'korwi para Torwa Mateiro, que está perto da entrada da Cratera Un'Goro.", tgo={{"Lar'korwi"}}},
    [4296] = {n="Tabuletas dos Sete", d="Leve a Transcrição de Tabuleta para Maxwort Uberraio nas Estepes Ardentes.", objs={"Tabuletas dos Sete"}},
    [4301] = {n="O poderoso U'cha", d="Leve Pelagem de U'cha para Torwa Mateiro na entrada da Cratera Un'Goro.", tgo={{"U'cha"}}},
    [4321] = {n="Entendendo tudo", d="Fale com J.D. Neri em um instante."},
    [4341] = {n="Kharan Feromalho", d="Viaje para Abismo Rocha Negra e encontre Kharan Feromalho.\nO Rei mencionou que Kharan estava preso lá — talvez seja bom procurar uma prisão."},
    [4421] = {n="A corrupção dos Flamejade", d="Mate 11 Devotos Vis Flamejade, 9 Assombrantes Flamejade, 9 Desgarrados Flamejade e Xavathras. Fale novamente com Eridan Brisazul na Selva Maleva quando a tarefa estiver completa.", tgo={{"Devoto Vil Flamejade"}, {"Assombrante Flamejade"}, {"Desgarrado Flamejade"}, {"Xavathras"}}},
    [4441] = {n="Ancientes aviltados", d="Viaje para Darnassus e use a Ampola de Eridan para coletar uma Ampola de Água Benta no Templo da Lua. Fale novamente com Eridan, levando a ampola cheia.", objs={"Fonte do Templo da Lua"}},
    [4442] = {n="Purificação!", d="Fale novamente com Eridan em alguns instantes."},
    [4449] = {n="Calça arriada!", d="Mate 8 Geólogos Ferro Negro e leve 15 pedaços de Seda para a pessoa que está trancada na casinha na Garganta Abrasadora.", tgo={{"Geólogo Ferro Negro"}, {}}, objs={"Granito de Alterac", "Baú Gasto", "Baú Sólido"}},
    [4450] = {n="Livro-Caixa de Tanaris", d="Pegue a cópia do Livro-Caixa de Rugov A. Massoaço e encontre os itens listados antes de ir falar com ele em Tanaris.", tgo={{}, {"Aranha Teia-de-vidro"}, {}, {"Jarquia"}}, objs={"Livro de A. Massoaço", "Caixote Danificado"}},
    [4491] = {n="O calor tá de matar", d="Leve Ringo até Espraga Froque, no Refúgio do Marshal.\nSe Ringo desmaiar, use o Cantil da Espraga para reanimá-lo."},
    [4492] = {n="Perdido!", d="Encontre Ringo no Pico Penacho de Fogo."},
    [4493] = {n="A marcha dos silitídeos", d="Fale com o Alquimista Almofarrista em Geringontzan."},
    [4495] = {n="Um bom amigo", d="Encontre Iverron perto da caverna ao norte."},
    [4496] = {n="Sururu na selva", d="Leve uma Glândula Odorífera Gorishi e 5 Amostras de Solo de Un'Goro ao Alquimista Almofarrista em Geringontzan.", tgo={{"Vespa Gorishi", "Gorishi Trabalhadora", "Gorishi Aniquiladora", "Gorishi Aguilhante", "Gorishi Escavadora", "Guarda da Colmeia Gorishi", "Rainha da Colmeia Gorishi"}, {}}, objs={"Monte de Terra de Un'Goro"}},
    [4501] = {n="Cuidado com os pterrordaxes", d="Mate 10 Pterrordaxes e 15 Pterrordaxes Frenéticos, então fale com Espraga Froque no Refúgio do Marshal.", tgo={{"Pterrordax"}, {"Pterrordax Frenético"}}},
    [4502] = {n="Atividade vulcânica", d="Colete 9 amostras das Cinzas de Un'Goro dos elementais de fogo ao redor do vulcão da Cratera Un'Goro, e leve-as para Fanny Quito, em Vila Catraca.", tgo={{"Elemental Calcinante", "Chama Viva", "Agni", "Invasor Fulgurante", "Barão Charr"}}},
    [4503] = {n="O Chislo quer voar!", d="Colete 8 Escamas de Dimetrodonte Palmado e 8 Escamas de Pterrordax Palmado para Chislo no Refúgio do Marshal.", tgo={{"Dimetrodonte Jovem", "Dimetrodonte", "Dimetrodonte Ancião"}, {"Pterrordax Jovem", "Pterrordax", "Pterrordax Frenético"}}},
    [4504] = {n="Supergrudento", d="Colete 12 amostras de Piche Supergrudento para Tran'rek em Geringontzan.", tgo={{"Monstro de Piche", "Tocaieiro de Piche", "Senhor do Piche", "Rastejante de Piche"}}},
    [4581] = {n="Kainet Brisacalma", d="Leve o Bilhete de Shindrell para Kainet Brisacalma em Cantilenda."},
    [4681] = {n="Deixa a água me levar", d="Recupere a Carcaça de Tartaruga Marinha da Tartaruga Marinha Descarnada nas águas a oeste de Auberdine, e então fale com Gwennyth Bly'Leggonde em Auberdine.", objs={"Tartaruga Marinha Descarnada"}},
    [4722] = {n="Tartaruga Marinha Encalhada", d="Leve a Carcaça de Tartaruga Marinha para Gwennyth Bly'Leggonde em Auberdine."},
    [4723] = {n="Criatura Marinha Encalhada", d="Leve os Ossos de Criaturas Marinhas para Gwennyth Bly'Leggonde em Auberdine."},
    [4725] = {n="Tartaruga marinha encalhada", d="Leve a Caixa com Marcações Estranhas para Gwennyth Bly'Leggonde em Auberdine."},
    [4726] = {n="Essência da Reprodução", d="Leve 8 Essências da Reprodução e o Draco-incarcinatrix 900 a Vera Brequim no Monte Candente, que fica nas Estepes Ardentes.", objs={"Essência da Reprodução"}},
    [4727] = {n="Tartaruga Marinha Encalhada", d="Leve a Carcaça de Tartaruga Marinha para Gwennyth Bly'Leggonde em Auberdine."},
    [4728] = {n="Criatura Marinha Encalhada", d="Leve os Ossos de Criaturas Marinhas para Gwennyth Bly'Leggonde em Auberdine."},
    [4730] = {n="Criatura Marinha Encalhada", d="Leve os Ossos de Criaturas Marinhas para Gwennyth Bly'Leggonde em Auberdine."},
    [4731] = {n="Tartaruga Marinha Encalhada", d="Leve a Caixa com Marcações Estranhas para Gwennyth Bly'Leggonde em Auberdine."},
    [4732] = {n="Tartaruga Marinha Encalhada", d="Leve a Carcaça de Tartaruga Marinha para Gwennyth Bly'Leggonde em Auberdine."},
    [4733] = {n="Criatura Marinha Encalhada", d="Leve os Ossos de Criaturas Marinhas para Gwennyth Bly'Leggonde em Auberdine."},
    [4740] = {n="PROCURA-SE: Lodofundo!", d="Encontre e mate o murloc conhecido como Lodofundo. Acredita-se que a criatura esteja defendendo as tendas dos murlocs ao sul de Auberdine, ao longo da costa.\nRelate a morte de Lodofundo à Sentinela Glynda Nal'Shea em Auberdine.", tgo={{"Lodofundo"}}},
    [4761] = {n="Trovejius Tecevento", d="Fale com Trovejius Tecevento em Auberdine."},
    [4762] = {n="Rio Fontescarpa", d="Vá para o norte de Auberdine até a primeira queda d'água ao longo do Rio Fontescarpa e consiga uma amostra do charco.\nLeve a Amostra do Rio Fontescarpa para Trovejius Tecevento em Auberdine.", objs={"Cliffspring River Waterfall"}},
    [4763] = {n="Os Bosquenero corrompidos", d="Encha a Bacia de Limpeza Vazia no Poço Lunar de Auberdine.\nObtenha uma amostra de fruta, noz e grão dos acampamentos dos pelursos Bosquenero ao norte.\nMisture tudo na bacia e coloque junto à fogueira próxima ao Rio Fontescarpa, no acampamento norte. E assim atraia o sátiro corruptor.\nPegue o Talismã de Corrupção e o leve para Trovejius Tecevento em Auberdine.", objs={"Bolsa de Demônios de Zabraxxis"}},
    [4811] = {n="O cristal vermelho", d="Viaje para o leste de Auberdine e procure por um grande cristal vermelho na montanha leste da Costa Negra. Relate o que você descobriu à Sentinela Glynda Nal'Shea, em Auberdine.", objs={"Cristal Vermelho Misterioso"}},
    [4812] = {n="Como cascatas", d="Encha o Tubo de Água Vazio no poço lunar de Auberdine, e depois investigue o cristal vermelho na encosta da montanha leste da Costa Negra.", objs={"Poço Lunar de Auberdine"}},
    [4813] = {n="Fragmentos incrustados", d="Relate o que você descobriu à Sentinela Glynda Nal'Shea, em Auberdine."},
    [4842] = {n="Fontes estranhas", d="Siga as instruções de Bruna Covaneve, depois fale novamente com ela."},
    [4861] = {n="Coruscante enfurecido", d="Encontre o acampamento destruído e os suprimentos de Jaron Moldapedra na parte sul de Hibérnia."},
    [4863] = {n="Coruscante enfurecido", d="Encontre a carroça destruída de Jaron Moldapedra."},
    [4864] = {n="Coruscante enfurecido", d="Pegue os Suprimentos do Jaron na neve, depois encontre o coruscante que roubou o amuleto de que Jaron falou.\nEntregue os Suprimentos do Jaron e o Amuleto de Penas Azuis para Jaron Moldapedra na cabana, em Hibérnia.", tgo={{}, {"Feruja Enlouquecida", "Feruja Lunamarca", "Feruja Berserk", "Guardião de Eluna"}}, objs={"Suprimentos do Jaron"}},
    [4901] = {n="Guardiões do altar", d="Proteja Ranshalla enquanto ela tenta reativar o Altar de Eluna. Relate suas descobertas a Erelas Ambarcéu, na Vila de Rut'theran."},
    [4902] = {n="Coruscante de Eluna", d="Fale com o Arquidruida Fandral Guenelmo em Darnassus."},
    [4906] = {n="Mais corrupção", d="Eridan Brisazul, na Selva Maleva, quer que você mate 8 Infernarautos Flamejade, 8 Traidores Flamejade, 8 Trapaceiros Flamejade e Xavaric. Fale novamente com Eridan quando a tarefa estiver concluída.", tgo={{"Infernarauto Flamejade"}, {"Traidor Flamejade"}, {"Trapaceiro Flamejade"}, {"Xavaric"}}},
    [4971] = {n="É questão de tempo", d="Use o Deslocador Temporal perto de um dos silos de Andorhal e desencave Parasitas Temporais.\nMate 15 Parasitas Temporais e depois devolva o Deslocador Temporal para Crona na Estalagem Andorhal, que fica nas Terras Pestilentas Ocidentais.", tgo={{"Parasita Temporal"}}},
    [4984] = {n="A vida selvagem também sofre", d="Destrua 8 Lobos Doentes e fale novamente com Mulgris Riofundo no Antro Repelente, que fica nas Terras Pestilentas Ocidentais.", tgo={{"Lobo Doente"}}},
    [4985] = {n="A vida selvagem também sofre", d="Destrua 8 Ursos-cinzentos Doentes e fale novamente com Mulgris Riofundo no Antro Repelente, que fica nas Terras Pestilentas Ocidentais.", tgo={{"Urso-cinzento Doente"}}},
    [4986] = {n="Galho de carvalho com glifos", d="Baseado na magia imbuída no galho de carvalho com glifos, sua entrega ao Círculo Cenariano em Darnassus é o próximo passo que o druida tauren buscava. Procure a ajuda de um dos druidas."},
    [5021] = {n="Antes tarde do que nunca", d="As divagações da mulher fantasmagórica indicavam que ela precisava que um pacote fosse entregue. Ela afirmou que ele estava no mesmo lugar que seu cavalo. Quanto ao local onde o cavalo está ou onde o pacote deve ser entregue, continua sendo impossível entender o fantasma."},
    [5022] = {n="Antes tarde do que nunca", d="Fale com os Administradores Reais de Ventobravo para saber o paradeiro da Bia Pedravil. Geralmente tem um agente do censo na Prefeitura."},
    [5048] = {n="Bondosa Bia", d="Encontre a Tia Bia em Ventobravo e veja se, de fato, ela é Bia Pedravil. Se for, talvez ela possa querer o pacote que Janice Pedravil lhe mandou."},
    [5050] = {n="Pingente da Sorte", d="Devolva o Meio-pingente da Sorte para Janice Pedravil nas Terras Pestilentas Ocidentais."},
    [5066] = {n="Um chamado às armas: as Terras Pestilentas!", d="Procure o Comandante Ashlam Punhobom. Ele montou base no Acampamento Ventogelante, ao norte das Montanhas de Alterac."},
    [5082] = {n="A ameaça dos Invernosos", d="Bruna Covaneve, de Hibérnia, quer que você mate 8 Desbravadores Invernosos, 8 Vigias do Covil dos Invernosos e 8 Totêmicos Invernosos.", tgo={{"Desbravador Invernoso"}, {"Vigia do Covil dos Invernosos"}, {"Totêmico Invernoso"}}},
    [5083] = {n="Aguardente Invernosa", d="Leve o Frasco Vazio de Aguardente para Bruna Covaneve em Hibérnia."},
    [5084] = {n="Cedendo à corrupção", d="Investigue o acampamento dos pelursos Lenha Morta na parte norte de Selva Maleva para encontrar alguma pista."},
    [5085] = {n="Meleca misteriosa", d="Informe Bruna Covaneve sobre as suas descobertas."},
    [5092] = {n="Abrindo caminho", d="Mate 10 Esfoladores Descarnados e 10 Carniçais Salivantes na Colina do Pesar.\nFale novamente com o Comandante Ashlam Punhobom no Acampamento Ventogelante, que fica nas Terras Pestilentas Ocidentais.", tgo={{"Esfolador Descarnado"}, {"Carniçal Salivante"}}},
    [5097] = {n="Você não vê as torres?", d="Usando a Tocha Sinalizadora, marque cada torre em Andorhal. Você tem que ficar na entrada da torre para conseguir marcá-la.\nDepois de marcar as quatro torres, leve a Tocha Sinalizadora de volta para o Comandante Ashlam Punhobom no Acampamento Ventogelante, que fica nas Terras Pestilentas Ocidentais.", tgo={{"Torre Um de Andorhal"}, {"Torre Dois de Andorhal"}, {"Torre Três de Andorhal"}, {"Torre Quatro de Andorhal"}}},
    [5149] = {n="A boneca de Pâmela", d="Encontre a boneca de Pâmela."},
    [5152] = {n="Tia Marlene", d="Fale com Marlene, ao sul das Ruínas de Andorhal."},
    [5153] = {n="Uma historiadora estranha", d="Leve o Anel de Casamento do Josefo para Crona.", objs={"Monumento do Josefo Trilharrubra"}},
    [5154] = {n="Os Anais da Vila das Flechas", d="Leve os Anais da Vila das Flechas para Crona em Andorhal.", objs={"Tomo Mofado"}},
    [5155] = {n="Forças de Jaedenar", d="Entre em Jaedenar e mate 4 Cães de Jaedenar, 4 Guardas de Jaedenar, 6 Adeptos de Jaedenar e 6 Sectários de Jaedenar. Depois, fale novamente com Greta Musgo no Casco, na Selva Maleva.", tgo={{"Cão de Jaedenar"}, {"Guardião de Jaedenar"}, {"Adepto de Jaedenar"}, {"Sectário de Jaedenar"}}},
    [5156] = {n="Verificar a corrupção", d="Procure e destrua 2 Feras Entrópicas e 2 Horrores Entrópicos enquanto explora o Vale das Escaras Pungentes. Depois de ver se as crateras ainda estão cheias de água contaminada com vileza, fale novamente com Taronn Pena Vermelha, na Selva Maleva.", tgo={{"Fera Entrópica"}, {"Horror Entrópico"}}},
    [5157] = {n="Coletar a água corrompida", d="Leve o Cantil Vazio para o Poço Lunar no meio de Jaedenar e encha-o. Depois, fale novamente com Greta Musgo no Casco na Selva Maleva.", objs={"Poço Lunar Corrompido de Jaedenar"}},
    [5158] = {n="À procura de auxílio espiritual", d="Leve a Água Corrompida do Poço Lunar para Islen Vidente da Água, nos Sertões."},
    [5159] = {n="O retorno da água purificada à Selva Maleva", d="Leve a Água Purificada do Poço Lunar para Greta Musgo no Casco, na Selva Maleva."},
    [5168] = {n="Heróis da Vila das Flechas", d="Leve o Incunábulo de Davil e o Escudo de Trilharrubra para Carlin Trilharrubra.", objs={"Incunábulo de Davil", "Escudo de Trilharrubra"}},
    [5181] = {n="Vilões da Vila das Flechas", d="Leve o Crânio de Horgus e a Espada Estilhaçada de Marduk para Carlin Trilharrubra na Capela Esperança da Luz.", objs={"Crânio de Horgus", "Espada Estilhaçada de Marduk"}},
    [5210] = {n="Irmão Carlin", d="Leve os Anais Estendidos da Vila das Flechas para Carlin Trilharrubra nas Terras Pestilentas Orientais."},
    [5211] = {n="Defensores da Vila das Flechas", d="Liberte 15 Espíritos da Vila das Flechas e fale novamente com Carlin Trilharrubra.", tgo={{"Espírito da Vila das Flechas"}}},
    [5215] = {n="Os caldeirões do Flagelo", d="Fale com a Alta-sacerdotisa Donélia no Morro do Ventogelante, que fica nas Terras Pestilentas Ocidentais."},
    [5216] = {n="Alvo: Campo Pedravil", d="Vá ao Campo Pedravil nas Terras Pestilentas Ocidentais para localizar e derrotar o Mestre do Caldeirão de lá. Ele pode ter uma chave que dê acesso ao caldeirão. Você precisa estar com a Garrafa do Campo Pedravil Vazia para guardar uma amostra dos venenos usados no caldeirão.", tgo={{"Mestre da Caldeira Bilevil"}}},
    [5217] = {n="Retorno ao Acampamento Ventogelante", d="Leve a Garrafa do Campo Pedravil Cheia à Alta-sacerdotisa Donélia no Acampamento Ventogelante, que fica nas Terras Pestilentas Ocidentais."},
    [5219] = {n="Alvo: Lágrimas de Dalson", d="Vá a Lágrimas de Dalson nas Terras Pestilentas Ocidentais para localizar e derrotar o Mestre do Caldeirão de lá, e use a chave dele para ter acesso ao caldeirão. Você precisa estar com a Garrafa das Lágrimas de Dalson Vazia para guardar uma amostra dos venenos usados no caldeirão.", tgo={{"Mestre da Caldeira Malvínio"}}},
    [5220] = {n="Retorno ao Acampamento Ventogelante", d="Leve a Garrafa das Lágrimas de Dalson Cheia à Alta-sacerdotisa Donélia no Acampamento Ventogelante, que fica nas Terras Pestilentas Ocidentais."},
    [5222] = {n="Alvo: Antro Repelente", d="Vá ao Antro Repelente nas Terras Pestilentas Ocidentais para localizar e derrotar o Mestre do Caldeirão de lá, e use a chave dele para ter acesso ao caldeirão. Você precisa estar com a Garrafa do Antro Repelente Vazia para guardar uma amostra dos venenos usados no caldeirão.", tgo={{"Mestre da Caldeira Rainério"}}},
    [5223] = {n="Retorno ao Acampamento Ventogelante", d="Leve a Garrafa do Antro Repelente Cheia à Alta-sacerdotisa Donélia no Acampamento Ventogelante, que fica nas Terras Pestilentas Ocidentais."},
    [5225] = {n="Alvo: Aridez de Garrão", d="Vá a Aridez de Garrão nas Terras Pestilentas Ocidentais para localizar e derrotar o Mestre do Caldeirão de lá, e use a chave dele para ter acesso ao caldeirão. Você precisa estar com a Garrafa da Aridez de Garrão Vazia para guardar uma amostra dos venenos usados no caldeirão.", tgo={{"Mestre da Caldeira Almafúria"}}},
    [5226] = {n="Retorno ao Acampamento Ventogelante", d="Leve a Garrafa da Aridez de Garrão Cheia à Alta-sacerdotisa Donélia no Acampamento Ventogelante, que fica nas Terras Pestilentas Ocidentais."},
    [5238] = {n="Missão cumprida!"},
    [5241] = {n="Tio Carlin", d="Encontre Carlin Trilharrubra."},
    [5244] = {n="Ruínas de Kel'Theril", d="Fale com Jaron Moldapedra na Aldeia Chuva Estelar."},
    [5245] = {n="Espíritos atormentados de Kel'Theril", d="Use a Picareta do Jaron para encontrar os quatro Fragmentos da Relíquia dos Altaneiros. Leve-os para Aurora Clamacéus nas Terras Pestilentas Orientais.", objs={"Fragmento da Relíquia dos Altaneiros"}},
    [5246] = {n="Fragmentos do passado", d="Encontre os Escritos Sagrados dos Altaneiros no Templo de Zin-Malor, em Azshara, e leve-os para Aurora Clamacéus, perto da Torre do Passo Norte nas Terras Pestilentas Orientais.", objs={"Escritos Sagrados dos Altaneiros"}},
    [5250] = {n="Chuva Estelar", d="Encontre a Chuva Estelar, em Hibérnia, e fale com Eol Correnoite."},
    [5261] = {n="Enzo Peleteiro", d="Fale com Enzo Peleteiro."},
    [5401] = {n="Ordem da Aurora Argêntea"},
    [5541] = {n="Sem munição não tem negócio", d="Entregue a Munição do Estremetiro para Hegnar Estremetiro em Dun Morogh.", objs={"Caixote de Munições"}},
    [5542] = {n="Cães demoníacos", d="Mate 20 Cães Pestilentos Miúdos, 5 Cães Pestilentos e 5 Cães Pestilentos Frenéticos. Fale novamente com Tirion Fordring quando a tarefa estiver concluída.", tgo={{"Cão Pestilento Miúdo"}, {"Cão Pestilento"}, {"Cão Pestilento Frenético"}}},
    [5543] = {n="Céu tingido de sangue", d="Mate 30 Quirópragos e fale novamente com Tirion Fordring.", tgo={{"Quiróprago"}}},
    [5544] = {n="Carne de verme carniceiro", d="Procure os Vermes Carniceiros e os Devoradores de Carniça da região. Mate-os e tire a carne. Fale novamente com Tirion Fordring depois que tiver juntado 15 Nacos de Carne de Verme Carniceiro.", tgo={{"Verme Carniceiro", "Devorador de Carniça"}}},
    [5545] = {n="Um feixe de encrenca", d="Leve 8 Feixes de Madeira para Raquel na Madeireira Vale do Leste.", objs={"Feixe de Lenha"}},
    [5601] = {n="Irmã Pâmela", d="Encontre Pâmela Trilharrubra na Vila das Flechas."},
    [5713] = {n="Um tiro, uma morte", d="Proteja a Sentinela Aynasha. Em seguida, fale com Onaeya no Entreposto de Maestra, que fica no Vale Gris."},
    [5742] = {n="Redenção", d="Escute o que Tirion Fordring tem a dizer.", tgo={{"Tirion Fordring"}}},
    [5762] = {n="Rosarães Guima", d="Leve o Caixote de Kravel para Rosarães Guima na Selva do Espinhaço."},
    [5781] = {n="Elixir de memórias esquecidas", d="Viaje para a Chácara Secreta, no extremo sul das Terras Pestilentas Orientais, e recupere o Martelo de Taelan. Fale novamente com Tirion Fordring ao completar seu objetivo.", tgo={{"Mercutio Devorapodre"}}},
    [5845] = {n="Da honra perdida", d="Viaje para o Vilarejo do Norte, na região nordeste das Terras Pestilentas Orientais, e recupere o Símbolo da Honra Perdida. Fale novamente com Tirion Fordring ao completar seu objetivo.", objs={"Símbolo da Honra Perdida"}},
    [5846] = {n="Do amor e da família", d="Viaje para a ilha de Castro das Flechas, na região centro-sul das Terras Pestilentas, e procure pistas sobre o paradeiro da pintura."},
    [5848] = {n="Do amor e da família", d="Viaje para Stratholme, na parte norte das Terras Pestilentas. No Bastião Escarlate, você encontrará a pintura \"Do Amor e da Família\", escondida atrás de outro quadro que retrata as luas gêmeas do nosso mundo.\nLeve a pintura de volta para Tirion Fordring.", objs={"Pintura Incompleta"}},
    [5863] = {n="O Complexo Dunamalho", d="Andi Lynn em Geringontzan quer que você destrua o Complexo Dunamalho. Para isso, deve matar 10 Brutamontes Dunamalho, 10 Impositores Dunamalho e Gor'marok, o Assolador.", tgo={{"Brutamontes Dunamalho"}, {"Impositor Dunamalho"}, {"Gor'marok, o Assolador"}}},
    [5903] = {n="Praga de cupins!", d="Use a Jarra de Cupins Vazia nos Cupinzeiros que há nas Terras Pestilentas Orientais. Após conseguir 100 Cupins das Terras Pestilentas, fale novamente com Nataniel Dumah no Acampamento Ventogelante, em Terras Pestilentas Ocidentais.", objs={"Cupinzeiro Grande"}},
    [5904] = {n="Praga de cupins!", d="Encontre um lugar apropriado para pôr o Barril de Cupins das Terras Pestilentas no centro da Serraria de Beiranorte, que fica nas Terras Pestilentas Ocidentais."},
    [6001] = {n="Corpo e coração", d="Aplique Poeira de Lua Cenariana na Pedra Luniscante de Auberdine para trazer Lunagarra. Então, enfrente Lunagarra e ganhe a força de corpo e coração que ele possui.\nFale com Mathrengyl Ursivagus em Darnassus quando você terminar.", tgo={{"Espírito de Lunagarra"}}},
    [6004] = {n="Negócios inacabados", d="Mate 2 Socorristas Escarlate, 2 Caçadores Escarlate, 2 Magos Escarlate e 2 Cavaleiros Escarlate antes de voltar a Kirsta Sombrafunda, nas Terras Pestilentas Ocidentais.", tgo={{"Socorrista Escarlate"}, {"Caçador Escarlate"}, {"Mago Escarlate"}, {"Cavaleiro Escarlate"}}},
    [6021] = {n="Zaeldarr, o Proscrito", d="Leve a Cabeça de Zaeldarr ao Zelador Alen na Capela Esperança da Luz.", tgo={{"Zaeldarr, o Proscrito"}}},
    [6023] = {n="Negócios inacabados", d="Mate o Guarda-caça Eiras e o Fidalgo Durgen antes de voltar à Kirsta Sombrafunda, nas Terras Pestilentas Ocidentais.", tgo={{"Guarda-caça Eiras"}, {"Fidalgo Durgen"}}},
    [6024] = {n="A súplica de Hameya", d="Mate o Infiltrador Hameya. Use a chave dele no Monturo de Terra atrás da Chácara Secreta.", tgo={{"Infiltrador Hameya"}}},
    [6025] = {n="Negócios inacabados", d="Entre em Amparo e encontre um lugar alto de onde possa ver a cidade e avaliar as forças da Cruzada Escarlate. Então fale novamente com Kirsta Sombrafunda nas Terras Pestilentas Ocidentais."},
    [6028] = {n="O relatório de Visteterna", d="Entregue o Relatório de Visteterna à Oficial Argêntea Cândida no Acampamento Ventogelante, que fica nas Terras Pestilentas Ocidentais."},
    [6030] = {n="Duque Nicolau Zverenhoff", d="Entregue o livro \"Estudos sobre Comunicação com Espíritos\" ao Duque Nicolau Zverenhoff na Capela Esperança da Luz, que fica nas Terras Pestilentas Orientais."},
    [6063] = {n="Domando a fera", d="Use o Bastão de Adestramento para domar uma Tocaieira Lenhateia. Pratique sua habilidade e depois devolva o Bastão de Adestramento a Dazalar em Dolanaar.", tgo={{"Tocaieira Lenhateia"}}},
    [6064] = {n="Domando a fera", d="Use o Bastão de Adestramento para domar uma Rochetusco Grande. Pratique sua habilidade e depois devolva o Bastão de Adestramento a Grif Selvacuore em Kharanos.", tgo={{"Rochetusco Grande"}}},
    [6084] = {n="Domando a fera", d="Use o Bastão de Adestramento para domar uma Leopardo da Neve. Pratique sua habilidade e depois fale novamente com Grif Selvacuore em Kharanos.", tgo={{"Leopardo da Neve"}}},
    [6085] = {n="Domando a fera", d="Use o Bastão de Adestramento para domar um Urso Garra de Gelo. Pratique sua habilidade e depois devolva o Bastão de Adestramento a Grif Selvacuore em Kharanos.", tgo={{"Urso Garra de Gelo"}}},
    [6086] = {n="Treinando a fera", d="Fale com Bélia Granitrondo em Altaforja."},
    [6101] = {n="Domando a fera", d="Use o Bastão de Adestramento para domar um Espreitador Sabre-da-noite. Treine sua perícia, e depois devolva o Bastão de Adestramento a Dazalar em Dolanaar.", tgo={{"Espreitador Sabre-da-noite"}}},
    [6102] = {n="Domando a fera", d="Use o Bastão de Adestramento para domar uma Guinchadora Estrígida. Treine sua perícia, e depois devolva o Bastão de Adestramento a Dazalar em Dolanaar.", tgo={{"Guinchadora Estrígida"}}},
    [6103] = {n="Treinando a fera", d="Fale com Jocasta no Enclave Cenariano, que fica em Darnassus."},
    [6134] = {n="Vá catar fantasmoplasma!", d="Leve 8 Fantasmoplasmas e o Caixote de Ímãs Fantasmais para Guido Zumbidorla na Desolação.", tgo={{"Espectro de Centauro"}}},
    [6182] = {n="O primeiro e último", d="Fale com Mathias Shaw na Cidade Velha de Ventobravo. Ele mora no Quartel."},
    [6183] = {n="Em honra aos mortos", d="Fale com Mathias Shaw novamente se desejar aceitar esta tarefa."},
    [6184] = {n="Flint Umbramais", d="Vá até o Acampamento Ventogelante, nas Terras Pestilentas Ocidentais, e encontre seu contato, Flint Umbramais."},
    [6185] = {n="As Pestes do Leste", d="Vasculhe as Terras Pestilentas Orientais em busca de pistas sobre o \"Arauto da Praga\" e os agentes da AVIN desaparecidos. Ser encontrar alguma Insígnia da AVIN, leve de volta para Flint Umbramais, no Acampamento Ventogelante.", objs={"Restos Humanos Esquartejados"}},
    [6341] = {n="O butim de Teldrassil", d="Leve a Coleção de Nessa para Vesprystus."},
    [6342] = {n="Voo para Auberdine", d="Viaje de hipogrifo para Auberdine com o mestre de hipogrifos Vesprystus, depois leve a Coleção de Nessa para Laird."},
    [6343] = {n="Resposta para Nessa", d="Leve a Resposta de Laird para Nessa Cantonegro."},
    [6344] = {n="Nessa Cantonegro", d="Fale com Nessa Cantonegro."},
    [6387] = {n="Alunos brilhantes", d="Leve a Lista de Brock para Thorgrum Borrelson, em Thelsamar."},
    [6388] = {n="Grif Trovino", d="Entregue as Picaretas Honorárias para Grif Trovino em Altaforja."},
    [6389] = {n="Praga de cupins!", d="Solte os Cupins das Terras Pestilentas na Serraria de Beiranorte, depois retorne com o Barril de Cupins das Terras Pestilentas até Nataniel Dumah, no Acampamento Ventogelante, que fica nas Terras Pestilentas Ocidentais."},
    [6391] = {n="Carona para Altaforja", d="Compre um voo de grifo para Altaforja do mestre de grifos Thorgrum Borrelson. Chegando lá, entregue a Lista de Brock para Golnir Topadão."},
    [6392] = {n="Fale novamente com Brock", d="Compre um voo de grifo para Thelsamar do mestre de grifos Grif Trovino. Chegando lá, entregue as Picaretas Honorárias para Brock Buscapedra."},
    [6603] = {n="Problema em Hibérnia!", d="Encontre Bruna Covaneve perto das fontes termais de Hibérnia."},
    [6604] = {n="Coruscante enfurecido", d="Fale com Jaron Moldapedra na Aldeia Chuva Estelar."},
    [7383] = {n="Coroa da Terra", d="Encha o Frasco de Ametista e leve-o de volta para Corithras Lunafúria em Dolanaar.", objs={"Poço Lunar da Clareira do Oráculo"}},
    [7701] = {n="PROCURA-SE: Feitor Maltorius", d="Nas profundezas do Fosso de Lava do Caldeirão, na Garganta Abrasadora, você encontrará o anão traidor dos Ferro Negro chamado Feitor Maltorius.\nMate o Feitor Maltorius, arranque a cabeça dele e leve-a para o Capitão-vigia Lolo Longalcance na Garganta Abrasadora para receber sua recompensa.", tgo={{"Feitor Maltorius"}}},
    [7722] = {n="Segue o fluxo", d="Em algum lugar do Fosso de Lava do Caldeirão você encontra as Instruções Secretas: Fluxo Ígneo que o Feitor Maltorius roubou. Encontre as instruções e devolva-as ao Mestre Ferreiro Queimatar na Garganta Abrasadora.", objs={"Instruções Secretas: Fluxo Ígneo"}},
    [7723] = {n="Malditos dedos gordos", d="Hansel Mão-pesada quer que você mate 20 Golens de Guerra Pesados.\nOs Golens de Guerra Pesados perambulam pelas áreas em torno do Caldeirão, na Garganta Abrasadora. Quando tiver matado a quantidade necessária, fale novamente com Hansel na Garganta Abrasadora.", tgo={{"Golem de Guerra Pesado"}}},
    [7724] = {n="Toco cru pegando fogo", d="Hansel Mão-pesada quer que você mate 20 Grandes Aranhas de Lava na Garganta Abrasadora. Você pode encontrá-las nos platôs e poços de lava do local.\nDepois de matar as Grandes Aranhas de Lava, fale novamente com Hansel Mão-pesada na Garganta Abrasadora.", tgo={{"Aranha de Lava Abrasadora"}}},
    [7727] = {n="Incendossauro? É de comer?", d="Hansel Mão-pesada quer que você mate 20 Incendossauros.\nEles ocupam as poças dentro do Fosso de Lava. O Fosso de Lava fica no Caldeirão da Garganta Abrasadora.\nDepois de matar os Incendossauros, fale novamente com Hansel Mão-pesada na Garganta Abrasadora.", tgo={{"Incendossauro"}}},
    [7728] = {n="OBJETOS ROUBADOS: Alcaraviz de Ferraria e Luneta do Espia", d="Encontre e devolva o Alcaraviz de Ferraria e a Luneta do Espia ao Capataz Scrange na Garganta Abrasadora.\nA única informação que você tem sobre esses itens é a seguinte: com certeza foram roubados por anões Ferro Negro. O Alcaraviz de Ferraria é uma ferramenta usada por ferreiros e a Luneta do Espia é um aparelho de monitoramento inestimável para vigias.", tgo={{"Vaporista Ferro Negro"}, {"Atalaia Ferro Negro"}}},
    [7729] = {n="TEMOS VAGAS: desbancando a concorrência", d="Mate 15 Capatazes Ferro Negro e 15 Feitores Ferro Negro. Depois, fale novamente com Capataz Scrange, na Garganta Abrasadora.", tgo={{"Capataz Ferro Negro"}, {"Feitor Ferro Negro"}}},
    [7733] = {n="Melhoria de qualidade", d="Leve 10 Pelegos de Yeti Cortifúria para Pradal McGrubben no Domínio de Plumaluna, em Feralas.", tgo={{"Yeti Cortifúria", "Ancião de Cortifúria", "Feraz de Cortifúria", "Furtivo Abominável"}}},
    [7735] = {n="Pelego imaculado de Yeti", d="Leve o Pelego Imaculado de Yeti para Pradal McGrubben no Domínio de Plumaluna, em Feralas."},
    [7791] = {n="Doação de lã", d="Usar/coletar: Granito de Alterac, Baú Gasto, Baú Gasto", objs={"Granito de Alterac", "Baú Gasto", "Baú Gasto"}},
    [7793] = {n="Doação de seda", d="Usar/coletar: Granito de Alterac, Baú Gasto, Baú Sólido", objs={"Granito de Alterac", "Baú Gasto", "Baú Sólido"}},
    [8360] = {n="Tudo por um marzipã", d="Use a expressão /dançar na frente da Estalajadeira Pala e ela lhe dará um Marzipã do Penhasco do Trovão em troca!", tgo={{"Estalajadeira Pala"}}},
    [8365] = {n="Chapéus de pirata, io-hô!", d="Sissi Ashando quer que você colete 20 Chapéus de Pirata dos Mares do Sul e leve-os para ela no Porto de Bondebico, em Tanaris.", tgo={{"Pirata dos Mares do Sul", "Flibusteiro dos Mares do Sul", "Estivador dos Mares do Sul", "Espadachim dos Mares do Sul", "André Barbarruiva", "Kregg Khaldus"}}},
    [8460] = {n="Aliando-se aos Presamatos", d="Grazle quer que você prove seu valor matando 6 Guerreiros de Lenha Morta, 6 Desbravadores de Lenha Morta e 6 Jardineiros de Lenha Morta. Quando você terminar, fale novamente com ele na parte sul da Selva Maleva, perto do Santuário Esmeralda.", tgo={{"Guerreiro de Lenha Morta"}, {"Desbravador de Lenha Morta"}, {"Jardineiro de Lenha Morta"}}},
    [8461] = {n="Lenha Morta do Norte", d="Nafien quer que você mate 6 Vigias do Covil de Lenha Morta, 6 Vingadores de Lenha Morta e 6 Xamãs de Lenha Morta. Fale novamente com ele na parte norte da Selva Maleva, perto da entrada do Domínio dos Presamatos.", tgo={{"Vigia do Covil de Lenha Morta"}, {"Vingador de Lenha Morta"}, {"Xamã de Lenha Morta"}}},
    [8462] = {n="Fale com Nafien", d="Viaje para o norte ao longo da estrada principal em Selva Maleva e fale com o pelurso chamado Nafien. Ele monta guarda diante da entrada do Domínio dos Presamatos."},
    [8464] = {n="Atividade Invernosa", d="Salfa quer que você mate 8 Xamãs Invernosos, 8 Vigias do Covil dos Invernosos e 8 Ursinos Invernosos. Salfa está perto da entrada do Domínio dos Presamatos, em Hibérnia.", tgo={{"Xamã Invernoso"}, {"Vigia do Covil dos Invernosos"}, {"Ursino Invernoso"}}},
    [86574] = {n="Entrega nas Torres de Pedra", d="Colete 6 Provisões das Torres de Pedra de Mantícoras Asaltiva e entregue-as à Estalajadeira Faralia.", tgo={{"Asaltiva Jovem", "Mantícora Asaltiva", "Predacéu Asaltiva", "Consorte Asaltiva", "Patriarca Asaltiva", "Freewind Post Wyvern"}}},
    [86758] = {n="Faca na ferida", d="Encontre e derrote o crocolisco Presadaga e traga de volta a faca de Marek.", tgo={{"Presadaga"}}},
    [87288] = {n="Pelagens de sabre-da-noite macias", d="Leve 6 Pelagens de Sabre-da-noite Macias a Aldria.", tgo={{"Sabre-da-noite"}}},
    [87760] = {n="Mergulhador sagrado", d="Encontre uma Senhora das Feras Escamarraio, mate-a e traga de volta seu Bastão do Domínio Profundo.", tgo={{"Senhora das Feras Escamarraio"}}},
    [91723] = {n="Instrumentos delicados", d="Mate 8 Geomantes Kobolds na Mina de Jaspe e volte a falar com Hamish Montavarga na Torre de Azora.", tgo={{"Geomante Kobold"}}},
    [91732] = {n="Aço de primeira", d="Colete 4 Ferramentas de Mineração na Mina de Jaspe e volte a falar com Hagar Leal na Madeireira Vale do Leste.", objs={"Ferramentas de Mineração"}},
    [91733] = {n="A jusante", d="Colete o Machado Encharcado, a Serra Encharcada e a Caixa de Ferramentas Encharcada a jusante da Madeireira Vale do Leste e volte a falar com Ormino Pelfórdio.", objs={"Machado Encharcado", "Serra Encharcada", "Caixa de Ferramentas Encharcada"}},
    [91740] = {n="Cabeça de Coaxinho", d="Entregue a Cabeça de Coaxinho a Mirella Rosa na Torre Serrana."},
    [91741] = {n="Livro mordiscado", d="Devolva o livro ao Irmão Paxeco."},
    [91743] = {n="Fome de conhecimento", d="Recupere 8 Livros Roubados dos kobolds no Vale de Vila Norte e devolva-os para o Irmão Paxeco.", tgo={{"Kobold Daninho", "Operário Kobold", "Trabalhador Kobold"}}},
    [91745] = {n="Consultoria em mineração", d="Fale com Kelsey Fargo na entrada da Mina da Serra do Eco, no Vale de Vila Norte."},
    [91752] = {n="Livro com figura também é leitura", d="Recupere um Saco de Livros com \"Ilustrações\" de Narf Descobrilho. Leve o saco para o Major Belmonte no interior da Abadia de Vila Norte.", tgo={{"Narf Descobrilho"}}},
    [91753] = {n="Uma aula encantadora", d="Kitta Ventígnea na Torre de Azora quer que você colete 3 Resíduos Luminosos.\nVocê pode obter Resíduos Luminosos desencantando Efígies de Cera Rústicas deixadas por Geomantes Kobolds."},
    [91758] = {n="Siga aquele kobold!", d="Fale com Tordrin Rigilâmina perto do estábulo atrás da Abadia de Vila Norte."},
    [91772] = {n="Silêncio! Área de caça a kobolds", d="Siga os rastros do kobold e apresente-se ao Delegado Durão em Vila d'Ouro com as suas descobertas e o Kit de Rastreamento de Kobolds.", objs={"Kobold Tracks"}},
    [91775] = {n="Devolução de livros", d="Encontre 6 Livros Perdidos e \"Diversão com Elementais\" e devolva-os ao Delegado Durão.", tgo={{"Nimsy"}, {"Minerador Kobold", "Tuneleiro Kobold"}}},
    [91777] = {n="Livros raros", d="Recupere os livros \"Geomancia para Jovens Magos Curiosos\" e \"Explicador Arcano: Coisas Mágicas em Palavras Simples\" e devolva-os ao Irmão Paxeco na Abadia de Vila Norte.", tgo={{"Geoescultor Yip", "Geomante Kobold"}, {"Mãe Veneno", "Geomante Kobold"}}},
    [92124] = {n="Inventário de livros", d="Fale com Daniel, o assistente do Irmão Paxeco, na biblioteca."},
    [92415] = {n="Lembre-se de que eu te amo", d="Leve a Carta Manchada de Sangue para a Matriarca Ananéri em Ventobravo."},
    [92460] = {n="A maturidade", d="Fale com Rorian, o Caça-alva, no Bosque Thendal."},
    [92461] = {n="Harmonia em equilíbrio", d="Mate 8 Vuldrens Juvenis no Bosque Thendal.", tgo={{"Vuldren Juvenil"}}},
    [92462] = {n="Investigação da infestação", d="Extermine 8 Cirromoscas Irritantes no Bosque Thendal.", tgo={{"Cirromosca Irritante"}}},
    [92463] = {n="A rainha cirromosca", d="Mate a Rainha Cirromosca no Bosque Thendal.", tgo={{"Rainha Cirromosca"}}},
    [92464] = {n="Agitação elemental", d="Fale com Yala Vigivento no Bosque Thendal."},
    [92465] = {n="Agitadores", d="Mate 6 Ventos Turbulentos e 7 Convertidos Al'Aketh no Bosque Thendal.", tgo={{"Convertido Al'Aketh"}, {"Ventos Turbulentos"}}},
    [92466] = {n="O chamado da terra", d="Leve um Sinete de Akir para o Moldavento Boro.", tgo={{"Brutamontes Al'Aketh", "Convertido Al'Aketh", "Neófito Al'Aketh", "Alta-sacerdotisa Lorthuna", "Sacerdote do Céu Aanders", "Comandante Belguilos"}}},
    [92467] = {n="O chamado da terra", d="Encontre o Cerro dos Espíritos e beba o Sapta da Terra."},
    [92468] = {n="O chamado da terra", d="Leve o Quartzo Grosseiro ao Moldavento Boro na Bosque Thendal."},
    [92469] = {n="Fale novamente com Rorian", d="Leve a notícia da presença do Al'Aketh para Rorian, o Caça-alva, no Bosque Thendal."},
    [92470] = {n="Má-triarca", d="Mate 8 Catadores Ursera e colete a cabeça da matriarca do covil, Urs'anah, no Bosque Thendal.", tgo={{"Catador Ursera"}, {"Urs'anah"}}},
    [92471] = {n="Aetheen das Ventanias", d="Fale com Aetheen das Ventanias no Bosque Thendal."},
    [92472] = {n="O próximo passo", d="Apresente-se à Oficial Aonda na Aldeia de Shen'dar."},
    [92473] = {n="Ocupação agressiva", d="Colete 6 Garras de Ursera Delgado de Urseras Delgado no Bosque Thendal.", tgo={{"Ursera Delgada"}}},
    [92474] = {n="Caindo com estilo", d="Salte do topo da torre de guarda no Bosque Thendal e use sua habilidade de Andar no Ar para desacelerar a queda."},
    [92479] = {n="Carta garranchada", d="Leia a Carta Garranchada e fale com o Tordrin Caulâmina na Abadia de Vila Norte."},
    [92481] = {n="A Student of the Arcane", d="Examine the Glowing Recall Crystal, then speak with Dorii Brightwhisper in Thendal Grove."},
    [92482] = {n="O caminho do caçador", d="Leia a Anotação Rabiscada e depois fale com Tai'ree Fitalonge no Bosque Thendal."},
    [92483] = {n="At Home in the Shadows", d="Read the Simple Note then speak with Akeri Duskblade within the watchtower in Thendal Grove."},
    [92484] = {n="Comunhão com os elementos", d="Examine o Cristal de Recordação Murmurante e depois fale com Moldavento Boro no Bosque Thendal."},
    [92485] = {n="Estudante da natureza", d="Leia o Pergaminho Dobrado e depois fale com Xyton Brisaprata no Bosque Thendal."},
    [92514] = {n="Boas-vindas à Aldeia de Shen'dar", d="Fale com Illaya Ventâmbar e Coriella Ventocalmo na Aldeia de Shen'dar.", tgo={{"Illaya Ventâmbar"}, {"Coriella Ventocalmo"}}},
    [92515] = {n="O gargalo das garraltivas", d="Colete 10 Pelagens de Garraltiva de Garraltivas no Planalto de Shen'dar.", tgo={{"Garraltiva"}}},
    [92516] = {n="Hipogrifos hostis", d="Mate 8 Jovens Hipogrifos, 6 Protetores Hipogrifos e uma Matriarca Hipogrifo no Planalto de Shen'dar.", tgo={{"Jovem Hipogrifo"}, {"Protetor Hipogrifo"}, {"Matriarca Hipogrifo"}}},
    [92517] = {n="O elemento criminoso", d="Elimine 10 Bandidos do Planalto e o líder deles, Bennic \"Malevento\", no Planalto de Shen'dar.", tgo={{"Bandido do Planalto"}, {"Bennic Malevento"}}},
    [92528] = {n="Entre os fiéis", d="Explore a Aldeia de Falaath para descobrir as intenções da seita no Planalto de Shen'dar.", tgo={{"Guarda-roupa"}}},
    [92529] = {n="Aldeia de Falaath", d="Procure o Missionário Jasaan perto da entrada da Aldeia de Falaath.\nSe você perder sua Marca de Akir, fale com Sania Fluviprata na Aldeia de Shen'dar para recuperar o efeito."},
    [92532] = {n="The Warrior's Path", d="Read the Crumpled Note you've been given, then seek out Blademaster Ren inside the Thendal Village watchtower."},
